// Domain Layer - Pure Business Logic
export interface Product {
  id: string;
  name: string;
  price: number;
}

export class ProductEntity {
  constructor(
    public readonly id: string,
    public readonly name: string,
    public readonly price: number
  ) {}

  applyDiscount(percent: number): void {
    if (percent < 0 || percent > 100) {
      throw new Error('Invalid discount percentage');
    }

    this.price = this.price * (1 - percent / 100);
  }
}

// Application Layer - Use Cases
export interface ApplyDiscountUseCase {
  execute(product: Product, percent: number): Promise<void>;
}

export class ApplyDiscount implements ApplyDiscountUseCase {
  constructor(
    private readonly productRepository: ProductRepository
  ) {}

  async execute(product: Product, percent: number): Promise<void> {
    if (percent < 0 || percent > 100) {
      throw new Error('Invalid discount percentage');
    }

    const updatedProduct = await this.productRepository.findById(product.id);

    if (!updatedProduct) {
      throw new Error('Product not found');
    }

    updatedProduct.applyDiscount(percent);
    await this.productRepository.save(updatedProduct);
  }
}

// Infrastructure Layer - Database Adapter
export interface ProductRepository {
  findById(id: string): Promise<ProductEntity | null>;
  save(product: ProductEntity): Promise<void>;
}

// Concrete Implementation
export class TypeORMProductRepository implements ProductRepository {
  async findById(id: string): Promise<ProductEntity | null> {
    // This would be implemented with actual database query
