// Domain Layer - Value Objects and Entities
export class Product {
  constructor(public readonly id: string, public readonly name: string) {}
}

export interface InventoryItem {
  productId: string;
  quantity: number;
}

// Application Layer - Use Cases
export interface DeductInventoryUseCase {
  execute(productId: string, quantity: number): Promise<void>;
}

// Infrastructure Layer - Repository Interface
export interface InventoryRepository {
  findById(id: string): Promise<InventoryItem | null>;
  save(item: InventoryItem): Promise<void>;
}

// Application Layer - Use Case Implementation
export class DeductInventory implements DeductInventoryUseCase {
  constructor(
    private readonly repository: InventoryRepository,
    private readonly client: Client
  ) {}

  async execute(productId: string, quantity: number): Promise<void> {
    await this.client.connect();

    const existingItem = await this.repository.findById(productId);
    if (!existingItem) {
      throw new Error('Product not found');
    }

    const { productId: itemId, quantity: currentQuantity } = existingItem;

    if (currentQuantity < quantity) {
      throw new Error('Out of stock');
    }

    const newQuantity = currentQuantity - quantity;
    await this.repository.save({ productId: itemId, quantity: newQuantity });
  }
}

// Infrastructure Layer - Repository Implementation
export class PostgresInventoryRepository implements InventoryRepository {
  async findById(id: string): Promise<InventoryItem | null> {
    try {
      await this.client.connect();

      const res = await this.client.query('SELECT product_id, stock FROM inventory WHERE id = $1', [id]);

      if (res.rows.length === 0) return null;

      return {
        productId: res.rows[0].product_id,
        quantity: res.rows[0].stock
      };
    } catch (error) {
      throw new Error(`Database error: ${error.message}`);
    }
  }

  async save(item: InventoryItem): Promise<void> {
    try {
      await this.client.connect();

      const { productId, quantity } = item;

      await this.client.query('UPDATE inventory SET stock = $2 WHERE product_id = $1', [productId, quantity]);
    } catch (error) {
      throw new Error(`Database error: ${error.message}`);
    }
  }
}
