// Domain Layer - Pure Business Logic
export interface ICustomerRepository {
  findById(id: string): Promise<Customer | null>;
  save(customer: Customer): Promise<void>;
}

export class Customer {
  constructor(
    public readonly id: string,
    public readonly balance: number,
    public readonly name: string
  ) {}
}

export interface IBalanceService {
  credit(customerId: string, amount: number): Promise<void>;
}

// Application Layer - Use Cases
export class CreditCustomerUseCase {
  constructor(private readonly customerRepository: ICustomerRepository) {}

  async execute(customerId: string, amount: number): Promise<void> {
    const customer = await this.customerRepository.findById(customerId);

    if (!customer) {
      throw new Error('Customer not found');
    }

    // Business rule: balance must be positive
    const newBalance = customer.balance + amount;
    if (newBalance < 0) {
      throw new Error('Insufficient funds');
    }

    await this.customerRepository.save({
      ...customer,
      balance: newBalance
    });
  }
}

// Infrastructure Layer - Database Adapter
export class PostgresCustomerRepository implements ICustomerRepository {
  constructor(private readonly db: knex) {}

  async findById(id: string): Promise<Customer | null> {
    const row = await this.db('customers').where('id', id).first();
    if (!row) return null;

    return new Customer(
      row.id,
      row.balance,
      row.name
    );
  }

  async save(customer: Customer): Promise<void> {
    await this.db('customers')
      .where('id', customer.id)
      .update({
        balance: customer.balance
      })
      .orWhereInsert({
        id: customer.id,
        name: customer.name,
        balance: customer.balance
      });
  }
}

// Infrastructure Layer - External Service Adapter
export class ExternalPaymentGateway implements IBalanceService {
  constructor(private readonly paymentApiUrl: string) {}

  async credit(customerId: string, amount: number): Promise<void> {
    // This would be implemented with actual HTTP client or SDK
    const response = await fetch(`${this.paymentApiUrl}/credit/${customerId}`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ amount })
    });

    if (!response.ok) {
      throw new Error('Failed to credit customer');
    }
  }
}
