// Infrastructure Layer - Database Implementation
export class InvoiceModel implements IInvoiceRepository {
  constructor(private readonly sequelize: Sequelize) {}

  async findById(id: number): Promise<IInvoice | null> {
    const invoice = await this.sequelize.models.Invoice.findByPk(id);
    return invoice ? new InvoiceEntity(invoice.id, invoice.total, invoice.paid) : null;
  }

  async save(invoice: IInvoice): Promise<void> {
    const existingInvoice = await this.sequelize.models.Invoice.findOne({
      where: { id: invoice.id }
    });

    if (existingInvoice) {
      await existingInvoice.update({ total: invoice.total, paid: invoice.isPaid });
    } else {
      await this.sequelize.models.Invoice.create({
        id: invoice.id,
        total: invoice.total,
        paid: invoice.isPaid
      });
    }
  }

  async markAsPaid(id: number): Promise<void> {
    const existingInvoice = await this.findById(id);
    if (!existingInvoice) {
      throw new Error('Invoice not found');
    }

    // In real implementation, you'd want to validate invariants here
    // For now, we'll assume the entity has proper validation
    const updatedInvoice = { ...existingInvoice, isPaid: true };
    await this.save(updatedInvoice);
  }
}
