// Domain Layer - Value Objects and Entities
export class CountryName {
  private constructor(private readonly value: string) {}

  static create(name: string): CountryName {
    if (!name || name.trim() === '') {
      throw new InvalidCountryNameError('Country name cannot be empty');
    }

    return new CountryName(name);
  }

  getValue(): string {
    return this.value;
  }
}

export class InvalidCountryNameError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'InvalidCountryNameError';
  }
}

// Application Layer - Use Cases
export interface GetCountryByIpUseCase {
  execute(ip: string): Promise<CountryName>;
}

export class GetCountryByIp implements GetCountryByIpUseCase {
  constructor(private readonly geolocationService: GeolocationService) {}

  async execute(ip: string): Promise<CountryName> {
    const response = await this.geolocationService.getCountryByIp(ip);
    return CountryName.create(response);
  }
}

// Infrastructure Layer - Ports & Adapters
export interface IGeolocationService {
  async getCountryByIp(ip: string): Promise<string>;
}

export class GeolocationServiceImpl implements IGeolocationService {
  async getCountryByIp(ip: string): Promise<string> {
    const response = await fetch(`https://ipapi.co/${ip}/json/`);
    const data = await response.json();
    return data.country_name;
  }
}

// Presentation Layer - Express Route
export class CountryController {
  constructor(private readonly getCountryUseCase: GetCountryByIpUseCase) {}

  async getCountries(req: Request, res: Response): Promise<void> {
    try {
      const ip = req.headers['x-forwarded-for'] || req.connection.remoteAddress;
      const countryName = await this.getCountryUseCase.execute(ip);

      res.json({ country_name: countryName.getValue() });
    } catch (error) {
      res.status(500).json({ error: 'Failed to get country' });
    }
  }
}
