  constructor(private readonly stripe: Stripe) {}

  async cancel(subscriptionId: string): Promise<void> {
    await this.stripe.subscriptions.cancel(subscriptionId);
  }

  async execute(request: SubscriptionCancellationRequest): Promise<SubscriptionCancelledEvent> {
    const cancelled = await this.cancel(request.subscriptionId.value);

    return new SubscriptionCancelledEvent(
      request.subscriptionId,
      new Date()
    );
  }
