  constructor(private readonly userRepository: UserRepository) {}

  async execute(email: string): Promise<User> {
    // Validate email
    if (!email.includes('@')) {
      throw new InvalidEmailError('Invalid email');
    }

    // Create user entity
    const user = new User(
      crypto.randomUUID(), // Unique ID generator
      email
    );

    return user;
  }
