// Domain Layer - Pure Business Logic
export interface Item {
  price: number;
  qty: number;
}

export interface TotalCalculator {
  calculate(items: Item[]): number;
}

// Application Layer - Use Case
export class ComputeTotalUseCase implements TotalCalculator {
  constructor(private readonly itemRepository: ItemRepository) {}

  async calculate(items: Item[]): Promise<number> {
    // Validate input
    const validation = this.itemRepository.validateItems(items);
    if (validation.isError) {
      throw new Error(validation.error);
    }

    // Calculate total
    return items.reduce((acc, item) => acc + (item.price * item.qty), 0);
  }
}

// Infrastructure Layer - Repository Interface
export interface ItemRepository {
  validateItems(items: Item[]): { isError: true; error: string } | { isError: false };
}

// Concrete Implementation
export class InMemoryItemRepository implements ItemRepository {
  private items: Item[] = [];

  async validateItems(items: Item[]): Promise<{ isError: true; error: string }> {
    // This is a simplified example - in real implementation, you'd want to validate business rules
    const duplicatePrice = new Set<number>();
    const negativeQty = new Set<number>();

    for (const item of items) {
      if (duplicatePrice.has(item.price)) {
        return { isError: true, error: 'Duplicate price found' };
      }

      if (negativeQty.has(item.qty)) {
        return { isError: true, error: 'Negative quantity found' };
      }

      duplicatePrice.add(item.price);
      negativeQty.add(item.qty);
    }

    return { isError: false };
  }

  async addItem(item: Item): Promise<void> {
    this.items.push(item);
  }

  async getItems(): Promise<Item[]> {
    return [...this.items];
  }
}

// Presentation Layer - Controller
export const computeTotalController = (
  totalCalculator: TotalCalculator
) => {
  return async (req: Request, res: Response): Promise<void> => {
    try {
      const items = req.body.items as Item[];

      const total = await totalCalculator.calculate(items);

      res.status(200).json({ total });
    } catch (error) {
      res.status(500).json({ error: 'Failed to calculate total' });
    }
  };
};
```

